import json,html,shutil
from pathlib import Path
root=Path(__file__).parent.parent;out=root/'output/individual-workflow-verification'
final=json.loads((out/'final-checks.json').read_text());cleanup=json.loads((out/'fixture-cleanup.json').read_text());preservation=json.loads((root/'output/ooru-meeting-audit/verification/preservation.json').read_text())
assert final['status']=='passed' and cleanup['status']=='completed' and preservation['status']=='passed'
shutil.copyfile(root/'output/ooru-meeting-audit/verification/preservation.json',out/'preservation.json')
ui=[]
for p in out.glob('*-ui.json'):
 d=json.loads(p.read_text());assert d['status']=='passed';ui.append(d)
layout=json.loads((out/'layout-final/results.json').read_text());assert layout['status']=='passed'
rows=''.join('<tr><td>'+html.escape(c['case'])+'</td><td>'+c['registration']+'</td><td>'+str(c['published'])+'</td><td>'+(c['change_request'] or '—')+'</td><td>Passed</td></tr>' for c in final['checks'])
